svg.script:
function trafficTogglePlay() {
  var els = document.querySelectorAll('.traffic-dot,.traffic-dash,.traffic-pulse');
  var first = els[0];
  var playing = !first || window.getComputedStyle(first).animationPlayState !== 'paused';
  els.forEach(function(el) {
    el.style.animationPlayState = playing ? 'paused' : 'running';
  });
  var icon = document.getElementById('traffic-play-icon');
  if (icon) icon.textContent = playing ? '\u25B6' : '\u23F8';
}
function trafficSetSpeed(mult) {
  document.documentElement.className = '';
  if (mult !== 1) {
    document.documentElement.classList.add('traffic-speed-' + (mult < 1 ? 'fast' : 'slow'));
  }
}
